package hutline;

import java.util.ArrayList;
import java.util.List;

/** Records which method bodies ran. */
public final class Log {
    public static final List<String> CALLS = new ArrayList<>();

    private Log() {
    }

    public static void add(String entry) {
        CALLS.add(entry);
    }
}

